# GIPS_RENDER_SECURE_ENV_20261103
# Token va admin ID faqat Render Dashboard -> Environment bo'limida saqlanadi.
# GitHubga maxfiy token, .env yoki config.env yuklamang.
BOT_TOKEN = os.environ.get('BOT_TOKEN', '').strip()
_admin_ids_raw = os.environ.get('ADMIN_IDS', '').strip()
try:
    ADMIN_IDS = {int(value) for value in re.split(r'[,;\s]+', _admin_ids_raw) if value}
except ValueError:
    raise SystemExit("ADMIN_IDS faqat raqamlardan iborat bo'lsin (masalan: 1888197854).")
# Render xizmatning HTTPS manzilini o'zi beradi; qo'lda URL yozish kerak emas.
WEBAPP_URL = (os.environ.get('RENDER_EXTERNAL_URL') or os.environ.get('WEBAPP_URL') or '').strip().rstrip('/')
MODE = 'webhook'
AUTO_TUNNEL = False
CLOUDFLARED_PATH = ''
TUNNEL_PROCESS = None
PORT = int(os.environ.get('PORT', '10000'))
LOCAL_PREVIEW_URL = f'http://127.0.0.1:{PORT}'
# Pullik Render disk /var/data ga o'rnatilsa baza va yuklamalar o'sha yerda saqlanadi.
# Bepul Renderda mahalliy SQLite / uploads qayta ishga tushishda yo'qolishi mumkin.
DATA_ROOT = Path('/var/data') if Path('/var/data').is_dir() else ROOT
DB_PATH = str(DATA_ROOT / 'gips_dekor.sqlite3')

if not re.fullmatch(r'[0-9]{5,}:[A-Za-z0-9_-]{20,}', BOT_TOKEN):
    raise SystemExit('XATO: Render -> Environment bo\'limida BOT_TOKEN ni kiriting (haqiqiy BotFather tokeni).')

if not ADMIN_IDS:
    raise SystemExit('XATO: Render -> Environment bo\'limida ADMIN_IDS ni kiriting.')

UPLOAD_DIR = DATA_ROOT / 'uploads'
ASSETS_DIR = ROOT / 'assets'
UPLOAD_DIR.mkdir(exist_ok=True)
