def now():
    return datetime.now(timezone.utc).isoformat(timespec='seconds')


@contextmanager
def connect():
    """Always close SQLite connections, including on failed transactions/selftests."""
    db = sqlite3.connect(DB_PATH, timeout=20)
    try:
        db.row_factory = sqlite3.Row
        db.execute('PRAGMA foreign_keys=ON')
        db.execute('PRAGMA busy_timeout=20000')
        with db:
            yield db
    finally:
        db.close()


def init_db():
    with connect() as db:
        db.execute('PRAGMA journal_mode=WAL')
        db.executescript('''
            CREATE TABLE IF NOT EXISTS users (
              tg_id INTEGER PRIMARY KEY, username TEXT NOT NULL DEFAULT '',
              first_name TEXT NOT NULL DEFAULT '', last_name TEXT NOT NULL DEFAULT '',
              phone TEXT NOT NULL DEFAULT '', registered INTEGER NOT NULL DEFAULT 0,
              lang TEXT NOT NULL DEFAULT 'uz', currency TEXT NOT NULL DEFAULT '',
              latitude REAL, longitude REAL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS categories (
              id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE,
              created_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS products (
              id INTEGER PRIMARY KEY AUTOINCREMENT, category_id INTEGER NOT NULL
                REFERENCES categories(id) ON DELETE RESTRICT,
              name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '',
              price INTEGER NOT NULL CHECK(price >= 0),
              currency TEXT NOT NULL DEFAULT 'KZT' CHECK(currency IN ('UZS','KZT')),
              price_uzs INTEGER CHECK(price_uzs >= 0),
              unit TEXT NOT NULL DEFAULT 'dona',
              image TEXT NOT NULL DEFAULT '',
              active INTEGER NOT NULL DEFAULT 1,
              created_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS orders (
              id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(tg_id),
              full_name TEXT NOT NULL, phone TEXT NOT NULL, username TEXT NOT NULL,
              region TEXT NOT NULL, city TEXT NOT NULL, address TEXT NOT NULL,
              latitude REAL, longitude REAL, notes TEXT NOT NULL DEFAULT '',
              total INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'KZT',
              status TEXT NOT NULL DEFAULT 'Yangi',
              created_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS order_items (
              id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL REFERENCES orders(id),
              product_id INTEGER, product_name TEXT NOT NULL, unit TEXT NOT NULL,
              quantity INTEGER NOT NULL, unit_price INTEGER NOT NULL
            );
            CREATE TABLE IF NOT EXISTS bot_states (
              tg_id INTEGER PRIMARY KEY, state TEXT NOT NULL, extra TEXT NOT NULL DEFAULT '{}'
            );
            CREATE INDEX IF NOT EXISTS idx_products_category ON products(category_id);
            CREATE INDEX IF NOT EXISTS idx_orders_user ON orders(user_id);
        ''')
        # Mavjud buyurtma va foydalanuvchilarni o'chirmasdan til ustunini qo'shish.
        user_columns = {r['name'] for r in db.execute('PRAGMA table_info(users)')}
        if 'lang' not in user_columns:
            db.execute("ALTER TABLE users ADD COLUMN lang TEXT NOT NULL DEFAULT 'uz'")
        if 'currency' not in user_columns:
            db.execute("ALTER TABLE users ADD COLUMN currency TEXT NOT NULL DEFAULT ''")
        product_columns = {r['name'] for r in db.execute('PRAGMA table_info(products)')}
        if 'price_uzs' not in product_columns:
            db.execute('ALTER TABLE products ADD COLUMN price_uzs INTEGER CHECK(price_uzs >= 0)')
        if 'currency' not in product_columns:
            # Oldingi mahsulotlar KZT bo'lib qoladi, admin kerak bo'lsa o'zgartiradi.
            db.execute("ALTER TABLE products ADD COLUMN currency TEXT NOT NULL DEFAULT 'KZT'")
        order_columns = {r['name'] for r in db.execute('PRAGMA table_info(orders)')}
        if 'currency' not in order_columns:
            db.execute("ALTER TABLE orders ADD COLUMN currency TEXT NOT NULL DEFAULT 'KZT'")


init_db()


def db_one(sql, args=()):
    with connect() as db:
        row = db.execute(sql, args).fetchone()
        return dict(row) if row else None


def db_all(sql, args=()):
    with connect() as db:
        return [dict(row) for row in db.execute(sql, args).fetchall()]


def run_sql(sql, args=()):
    with connect() as db:
        return db.execute(sql, args).lastrowid


def get_state(uid):
    row = db_one('SELECT state,extra FROM bot_states WHERE tg_id=?', (uid,))
    return (row['state'], json.loads(row['extra'])) if row else ('', {})


def set_state(uid, state, extra=None):
    run_sql('INSERT INTO bot_states(tg_id,state,extra) VALUES(?,?,?) '
            'ON CONFLICT(tg_id) DO UPDATE SET state=excluded.state,extra=excluded.extra',
            (uid, state, json.dumps(extra or {}, ensure_ascii=False)))


def clear_state(uid):
    run_sql('DELETE FROM bot_states WHERE tg_id=?', (uid,))


def clean(s, limit=300):
    return str(s or '').strip()[:limit]


def esc(s):
    return html.escape(str(s or ''), quote=False)


def money(v, currency='KZT'):
    if v is None:
        return 'Narx belgilanmagan'
    return f'{int(v):,}'.replace(',', ' ') + (' so‘m' if currency == 'UZS' else ' ₸')


