def uz_to_cyrillic(value):
    """Botdagi o‘zbekcha UI matnini kirillga o‘tkazish; HTML teglar saqlanadi."""
    mapping = {
        'sh':'ш', 'ch':'ч', 'ng':'нг', 'g‘':'ғ', 'gʻ':'ғ', "g'":'ғ',
        'o‘':'ў', 'oʻ':'ў', "o'":'ў', 'yo':'ё', 'yu':'ю', 'ya':'я', 'ye':'е',
        'a':'а', 'b':'б', 'd':'д', 'e':'е', 'f':'ф', 'g':'г', 'h':'ҳ',
        'i':'и', 'j':'ж', 'k':'к', 'l':'л', 'm':'м', 'n':'н', 'o':'о',
        'p':'п', 'q':'қ', 'r':'р', 's':'с', 't':'т', 'u':'у', 'v':'в',
        'x':'х', 'y':'й', 'z':'з', 'c':'ц', "'":'ъ', '‘':'ъ', 'ʻ':'ъ',
    }
    pattern = re.compile(r"sh|ch|ng|g[‘ʻ']|o[‘ʻ']|yo|yu|ya|ye|[a-z‘ʻ']", re.I)
    def convert_text(text):
        def sub(m):
            token = m.group(0)
            out = mapping.get(token.lower(), token)
            if token.isupper(): return out.upper()
            if token[0].isupper(): return out[0].upper() + out[1:]
            return out
        return pattern.sub(sub, text)
    return ''.join(piece if piece.startswith('<') or piece.startswith('&') else convert_text(piece)
                   for piece in re.split(r'(<[^>]*>|&(?:[A-Za-z]+|#\d+);)', str(value)))


def user_lang(uid):
    row = db_one('SELECT lang FROM users WHERE tg_id=?', (uid,))
    value = row.get('lang', 'uz') if row else 'uz'
    return value if value in LANGUAGES else 'uz'


def t_user(uid, uz, ru):
    lang = user_lang(uid)
    if lang == 'ru': return ru
    if lang == 'uz_cy': return uz_to_cyrillic(uz)
    return uz


def status_for_user(status, uid):
    if user_lang(uid) == 'uz_cy': return uz_to_cyrillic(status)
    if user_lang(uid) != 'ru': return status
    return {
        'Yangi': 'Новый', 'Qabul qilindi': 'Принят',
        'Tayyorlanmoqda': 'Готовится', 'Yetkazilmoqda': 'Доставляется',
        'Yakunlandi': 'Завершён', 'Bekor qilindi': 'Отменён',
    }.get(status, status)


