def phone_ok(s):
    # +7 (Qozog'iston/Rossiya), +90 (Turkiya), +998 (O'zbekiston)
    # va boshqa E.164 xalqaro raqamlar; 9 raqamli UZ raqamiga +998 qo'shiladi.
    digits = re.sub(r'\D', '', s or '')
    if len(digits) == 9:
        digits = '998' + digits
    if 10 <= len(digits) <= 15 and digits[0] != '0':
        return '+' + digits
    return None


def save_tg_user(u):
    if not u: return
    with connect() as db:
        db.execute('''INSERT INTO users(tg_id,username,first_name,last_name,created_at,updated_at)
           VALUES(?,?,?,?,?,?) ON CONFLICT(tg_id) DO UPDATE SET
           username=excluded.username,updated_at=excluded.updated_at''',
           (u.id, u.username or '', '', '', now(), now()))


def public_app_url():
    """On Render, RENDER_EXTERNAL_URL is supplied automatically at runtime."""
    if WEBAPP_URL.startswith('https://'):
        return WEBAPP_URL
    return ''


def open_app(chat_id, uid=None):
    """Inline Web App button opens the storefront inside Telegram."""
    uid = uid or chat_id
    url = public_app_url()
    if not url:
        bot.send_message(chat_id, t_user(uid,
            '⚠️ <b>Mini App ulanishi hozircha tayyor emas.</b>\n\nRender Deploy holatini tekshiring.',
            '⚠️ <b>Мини-приложение пока недоступно.</b>\n\nПроверьте состояние Render Deploy.'))
        return
    markup = types.InlineKeyboardMarkup()
    markup.add(types.InlineKeyboardButton(t_user(uid, '🛍 Mini Appni ochish', '🛍 Открыть магазин'),
                                         web_app=types.WebAppInfo(url)))
    markup.row(types.InlineKeyboardButton('🇺🇿 O‘zbek lotin', callback_data='lang_uz'),
               types.InlineKeyboardButton('🇺🇿 Ўзбек кирилл', callback_data='lang_uz_cy'))
    markup.row(types.InlineKeyboardButton('🇷🇺 Русский', callback_data='lang_ru'))
    # A separate in-chat button always works even if Telegram's persistent menu is unavailable.
    try:
        web_info = types.WebAppInfo(url)
        try:
            menu = types.MenuButtonWebApp(text='🛍 Gips Dekor', web_app=web_info)
        except TypeError:  # older pyTelegramBotAPI releases require the explicit type
            menu = types.MenuButtonWebApp(type='web_app', text='🛍 Gips Dekor', web_app=web_info)
        bot.set_chat_menu_button(chat_id=chat_id, menu_button=menu)
    except Exception as ex:
        print('Mini App menu button:', ex)
    bot.send_message(chat_id, t_user(uid,
        '✅ <b>Ro‘yxatdan o‘tdingiz!</b>\nQuyidagi tugmani bosing — do‘kon Telegram ichida ochiladi:',
        '✅ <b>Регистрация завершена!</b>\nНажмите кнопку ниже, чтобы открыть магазин в Telegram.'),
        reply_markup=markup)


