def photo_save(msg):
    """Telegram Photo yoki rasm-hujjatni qabul qilish (asl sifatdagi JPEG/PNG/WebP)."""
    try:
        meta = (msg.photo[-1] if msg.content_type == 'photo' and msg.photo
                else msg.document if msg.content_type == 'document' else None)
        if not meta or (meta.file_size and meta.file_size > 8 * 1024 * 1024):
            return None
        if msg.content_type == 'document':
            if (meta.mime_type or '').lower() not in {'image/jpeg', 'image/png', 'image/webp'}:
                return None
        file_info = bot.get_file(meta.file_id)
        data = bot.download_file(file_info.file_path)
        if not data or len(data) > 8 * 1024 * 1024:
            return None
        # Fayl nomiga ishonmaslik: fayl sarlavhasiga qarab haqiqiy kengaytma.
        if data.startswith(b'\xff\xd8\xff'):
            extension = '.jpg'
        elif data.startswith(b'\x89PNG\r\n\x1a\n'):
            extension = '.png'
        elif data.startswith(b'RIFF') and data[8:12] == b'WEBP':
            extension = '.webp'
        else:
            return None
        name = secrets.token_hex(16) + extension
        (UPLOAD_DIR / name).write_bytes(data)
        return '/uploads/' + name
    except Exception as ex:
        print('photo_save:', ex)
        return None


