@bot.message_handler(content_types=['text', 'contact', 'photo', 'document', 'location'])
def on_message(m):
    if m.chat.type != 'private': return
    uid = m.from_user.id
    save_tg_user(m.from_user)
    if m.content_type == 'location':
        with connect() as db:
            db.execute('UPDATE users SET latitude=?,longitude=?,updated_at=? WHERE tg_id=?',
                       (m.location.latitude, m.location.longitude, now(), uid))
        bot.reply_to(m, '📍 Geolokatsiyangiz qabul qilindi. Yangi buyurtmalarga qo‘shiladi.')
        return
    state, extra = get_state(uid)
    val = clean(m.text, 700) if m.content_type == 'text' else ''

    if state == 'register_phone':
        if m.content_type == 'contact':
            if m.contact.user_id and m.contact.user_id != uid:
                bot.reply_to(m, t_user(uid, 'Faqat o‘zingizning raqamingizni yuboring.', 'Отправьте только свой номер телефона.')); return
            phone = phone_ok(m.contact.phone_number)
        else: phone = phone_ok(val)
        if not phone:
            bot.reply_to(m, t_user(uid, '❌ Raqam xato. +7, +90 yoki +998 bilan yuboring.', '❌ Неверный номер. Укажите номер с +7, +90 или +998.'))
            return
        run_sql('UPDATE users SET phone=?,updated_at=? WHERE tg_id=?', (phone, now(), uid))
        set_state(uid, 'register_name')
        bot.send_message(m.chat.id, t_user(uid,
            '✅ Telefon raqamingiz qabul qilindi.\n\n👤 <b>Ism va familiyangizni</b> yozing:',
            '✅ Номер телефона принят.\n\n👤 Напишите <b>имя и фамилию</b>:'),
            reply_markup=types.ReplyKeyboardRemove())
        return
    if state == 'register_name':
        parts = val.split()
        if len(parts) < 2 or len(val) > 100 or m.content_type != 'text':
            bot.reply_to(m, t_user(uid, 'Ism va familiyangizni birga yozing. Masalan: Ali Valiyev', 'Напишите имя и фамилию вместе. Например: Иван Иванов.'))
            return
        firstname, lastname = parts[0], ' '.join(parts[1:])
        run_sql('UPDATE users SET first_name=?,last_name=?,registered=1,updated_at=? WHERE tg_id=?',
                (firstname, lastname, now(), uid))
        clear_state(uid)
        send_admin_button(uid)
        open_app(m.chat.id, uid)
        return

    if m.content_type == 'text' and val == ADMIN_BUTTON and access(uid):
        clear_state(uid)
        admin_menu(m.chat.id)
        return

    if not access(uid):
        bot.reply_to(m, t_user(uid, '🛍 Katalogni ochish uchun /start ni bosing.', '🛍 Чтобы открыть каталог, нажмите /start.'))
        return
    if not state:
        bot.reply_to(m, '🛠 Admin panel uchun pastdagi tugmani bosing.')
        return
    if state not in STATES:
        clear_state(uid); admin_menu(m.chat.id); return
    if state == 'new_category':
        if m.content_type != 'text' or len(val) < 2 or len(val) > 80:
            bot.reply_to(m, 'Kategoriya nomi 2–80 belgi bo‘lsin.'); return
        try: run_sql('INSERT INTO categories(name,created_at) VALUES(?,?)', (val, now()))
        except sqlite3.IntegrityError:
            bot.reply_to(m, 'Bu kategoriya oldin qo‘shilgan.'); return
        clear_state(uid); admin_menu(m.chat.id, f'✅ <b>{esc(val)}</b> kategoriyasi qo‘shildi.')
        return
    if state == 'product_name':
        if not (2 <= len(val) <= 140): bot.reply_to(m, 'Mahsulot nomini yozing (2–140 belgi).'); return
        extra['name'] = val
        set_state(uid, 'product_currency', extra)
        bot.reply_to(m, '💱 <b>Mahsulot narxi qaysi valyutada?</b>\nQuyidagi tugmalardan birini tanlang:',
                     reply_markup=product_currency_keyboard())
        return
    if state == 'product_currency':
        bot.reply_to(m, 'Valyutani inline tugmalardan tanlang.', reply_markup=product_currency_keyboard())
        return
    if state in {'product_price','edit_price'}:
        digit = val.replace(' ', '')
        if m.content_type != 'text' or not digit.isdigit() or int(digit) > 1_000_000_000:
            bot.reply_to(m, 'Narxni faqat raqam bilan kiriting (0 dan 1 mlrd gacha).'); return
        chosen_currency = extra.get('currency')
        if chosen_currency not in CURRENCIES:
            bot.reply_to(m, 'Valyuta belgilanmagan. /cancel bosing va qayta urinib ko‘ring.'); return
        if state == 'edit_price':
            run_sql('UPDATE products SET price=?,currency=? WHERE id=?',
                    (int(digit), chosen_currency, extra['id']))
            clear_state(uid); admin_menu(m.chat.id, '✅ Mahsulot narxi va valyutasi yangilandi.'); return
        extra['price'] = int(digit)
        set_state(uid, 'product_unit', extra)
        bot.reply_to(m, '📏 O‘lchov birligi: <b>dona</b>, <b>metr</b>, <b>m²</b>, <b>xizmat</b> yoki boshqasi:')
        return
    if state in {'product_unit','edit_unit'}:
        if not (1 <= len(val) <= 25): bot.reply_to(m, 'O‘lchov birligini yozing (1–25 belgi).'); return
        if state == 'edit_unit':
            run_sql('UPDATE products SET unit=? WHERE id=?', (val, extra['id']))
            clear_state(uid); admin_menu(m.chat.id, '✅ O‘lchov birligi yangilandi.'); return
        extra['unit'] = val
        set_state(uid, 'product_desc', extra)
        bot.reply_to(m, '📝 Mahsulot/xizmat tavsifini yozing (yoki /skip):')
        return
    if state in {'product_desc','edit_desc'}:
        if m.content_type != 'text': bot.reply_to(m, 'Tavsifni matn ko‘rinishida yuboring.'); return
        if state == 'edit_desc':
            run_sql('UPDATE products SET description=? WHERE id=?', ('' if val == '/skip' else val, extra['id']))
            clear_state(uid); admin_menu(m.chat.id, '✅ Tavsif yangilandi.'); return
        extra['desc'] = '' if val == '/skip' else val
        set_state(uid, 'product_photo', extra)
        bot.reply_to(m, '🖼 Mahsulotning <b>rasmini</b> yuboring: oddiy foto yoki sifatni saqlash uchun <b>Fayl (Document)</b> sifatida JPG, PNG, WebP. Yoki tayyor rasmni tanlang. Rasm qo‘shmaslik: /skip', reply_markup=sample_photos_kb())
        return
    if state in {'product_photo', 'edit_photo'}:
        image = '' if val == '/skip' else photo_save(m) if m.content_type in {'photo','document'} else None
        if image is None:
            bot.reply_to(m, '❌ Rasm ochilmadi. JPEG, PNG yoki WebP formatidagi haqiqiy rasmni <b>Foto</b> yoki <b>Fayl</b> sifatida yuboring (8 MB gacha). Yoki /skip bosing.'); return
        if state == 'edit_photo':
            if image: run_sql('UPDATE products SET image=? WHERE id=?', (image, extra['id']))
            clear_state(uid); admin_menu(m.chat.id, '✅ Rasm yangilandi.' if image else 'ℹ️ Rasm o‘zgarmadi.')
            return
        finish_product(m.chat.id, uid, extra, image)
        return
    if state == 'edit_name':
        if not 2 <= len(val) <= 140: bot.reply_to(m, '2–140 belgidan iborat nom yozing.'); return
        run_sql('UPDATE products SET name=? WHERE id=?', (val, extra['id']))
        clear_state(uid); admin_menu(m.chat.id, '✅ Nomi yangilandi.'); return


@bot.callback_query_handler(func=lambda c: True)
def callback(c):
    uid = c.from_user.id
    key = c.data or ''
    if key in {'lang_uz', 'lang_uz_cy', 'lang_ru'}:
        if c.message.chat.type != 'private':
            bot.answer_callback_query(c.id, 'Faqat shaxsiy chatda / Только в личном чате')
            return
        save_tg_user(c.from_user)
        chosen = key[5:]
        run_sql('UPDATE users SET lang=?,updated_at=? WHERE tg_id=?', (chosen, now(), uid))
        bot.answer_callback_query(c.id, {'uz':'🇺🇿 O‘zbek lotin','uz_cy':'🇺🇿 Ўзбек кирилл','ru':'🇷🇺 Русский'}[chosen])
        after_language_selected(c.message.chat.id, uid)
        return
    if not access(uid):
        bot.answer_callback_query(c.id, 'Admin huquqi yo‘q!', show_alert=True); return
    bot.answer_callback_query(c.id)
    chat_id = c.message.chat.id
    if key.startswith('sample_'):
        name = key[7:]
        if name not in {'karniz','rozetka','panel','kamin'}: return
        state,extra = get_state(uid)
        if state not in {'product_photo','edit_photo'}:
            bot.send_message(chat_id, 'Rasm tanlash uchun avval mahsulot qo‘shishni boshlang.'); return
        img_path = '/assets/' + name + '.jpg'
        if state == 'product_photo': finish_product(chat_id, uid, extra, img_path)
        else:
            run_sql('UPDATE products SET image=? WHERE id=?', (img_path, extra['id']))
            clear_state(uid); admin_menu(chat_id, '✅ Tayyor rasm qo‘shildi.')
        return
    if key == 'main': clear_state(uid); admin_menu(chat_id); return
    if key == 'cat_new':
        set_state(uid, 'new_category')
        bot.send_message(chat_id, '📂 <b>Yangi kategoriya nomini</b> kiriting.\nMasalan: Gips karnizlar\nBekor qilish: /cancel')
        return
    if key == 'cats':
        cats = db_all('SELECT c.id,c.name,(SELECT COUNT(*) FROM products p WHERE p.category_id=c.id) n FROM categories c ORDER BY c.id')
        kb = types.InlineKeyboardMarkup(row_width=1)
        for cat in cats[:80]:
            kb.add(types.InlineKeyboardButton(f'🗑 {cat["name"]} ({cat["n"]} mahsulot)', callback_data=f'catdel_{cat["id"]}'))
        kb.add(types.InlineKeyboardButton('⬅️ Ortga', callback_data='main'))
        bot.send_message(chat_id, '📂 Kategoriyalar. O‘chirish uchun tanlang:' if cats else 'Kategoriya hali yo‘q.', reply_markup=kb)
        return
    if key.startswith('catdel_'):
        cat = db_one('SELECT id,name FROM categories WHERE id=?', (key[7:],))
        if not cat: bot.send_message(chat_id, 'Kategoriya topilmadi.'); return
        count = db_one('SELECT COUNT(*) n FROM products WHERE category_id=?', (cat['id'],))['n']
        if count:
            bot.send_message(chat_id, f'⚠️ {esc(cat["name"])}: {count} ta mahsulot bor. Avval mahsulotlarni o‘chiring.'); return
        kb = types.InlineKeyboardMarkup().add(
            types.InlineKeyboardButton('✅ Ha, o‘chirish', callback_data=f'catyes_{cat["id"]}'),
            types.InlineKeyboardButton('❌ Yo‘q', callback_data='cats'))
        bot.send_message(chat_id, f'❗ <b>{esc(cat["name"])}</b> kategoriyasi o‘chirilsinmi?', reply_markup=kb)
        return
    if key.startswith('catyes_'):
        try: run_sql('DELETE FROM categories WHERE id=?', (key[7:],))
        except sqlite3.IntegrityError: bot.send_message(chat_id, '❌ Bu kategoriya ichida mahsulot bor.'); return
        admin_menu(chat_id, '✅ Kategoriya o‘chirildi.'); return
    if key in {'product_currency_UZS', 'product_currency_KZT'}:
        state, extra = get_state(uid)
        if state != 'product_currency':
            bot.send_message(chat_id, 'Avval yangi mahsulot qo‘shishni boshlang.'); return
        chosen = key.removeprefix('product_currency_')
        extra['currency'] = chosen
        set_state(uid, 'product_price', extra)
        bot.send_message(chat_id, f'💰 <b>{"So‘m" if chosen == "UZS" else "Tenge"}dagi narxni</b> yozing. '
                                  f'Masalan: <code>{"150000" if chosen == "UZS" else "8500"}</code>')
        return
    if key.startswith('edit_currency_') and key[14:].isdigit():
        product_id = int(key[14:])
        if not db_one('SELECT id FROM products WHERE id=?', (product_id,)):
            bot.send_message(chat_id, 'Mahsulot topilmadi.'); return
        bot.send_message(chat_id, '💱 <b>Mahsulot uchun yangi valyutani tanlang:</b>\n'
                                  'Keyin narxni qaytadan kiritasiz.',
                         reply_markup=product_currency_keyboard(f'edit_product_currency_{product_id}_'))
        return
    edit_currency_match = re.fullmatch(r'edit_product_currency_(\d+)_(UZS|KZT)', key)
    if edit_currency_match:
        product_id = int(edit_currency_match.group(1))
        chosen = edit_currency_match.group(2)
        if not db_one('SELECT id FROM products WHERE id=?', (product_id,)):
            bot.send_message(chat_id, 'Mahsulot topilmadi.'); return
        set_state(uid, 'edit_price', {'id': product_id, 'currency': chosen})
        bot.send_message(chat_id, f'💰 Yangi narxni {"so‘mda" if chosen == "UZS" else "tengeda"} yozing:')
        return
    if key == 'prod_new':
        cats = db_all('SELECT * FROM categories ORDER BY name')
        if not cats:
            bot.send_message(chat_id, '⚠️ Avval kategoriya qo‘shing.', reply_markup=kb_admin()); return
        kb = types.InlineKeyboardMarkup(row_width=1)
