@app.post('/api/order')
@authorized
def place_order():
    data = request.get_json(silent=True)
    if not isinstance(data, dict): return jsonify(error='JSON ma’lumot yuboring.'),400
    region = clean(data.get('region'), 100)
    city = clean(data.get('city'), 100)
    address = clean(data.get('address'), 300)
    notes = clean(data.get('notes'), 600)
    if region not in COUNTRIES or not city or len(address) < 5:
        return jsonify(error='Davlatni tanlang, shahar va aniq manzilni kiriting.'),400
    lat = data.get('latitude')
    lon = data.get('longitude')
    if (lat is None) != (lon is None): return jsonify(error='Koordinatalar noto‘g‘ri.'),400
    if lat is not None:
        try:
            lat, lon = float(lat), float(lon)
            if not (-90 <= lat <= 90 and -180 <= lon <= 180): raise ValueError()
        except (ValueError, TypeError): return jsonify(error='Joylashuv koordinatalari noto‘g‘ri.'),400
    else:
        lat, lon = request.tg_user['latitude'], request.tg_user['longitude']
    items = data.get('items')
    if not isinstance(items, list) or not 1 <= len(items) <= 30:
        return jsonify(error='Savat bo‘sh yoki juda ko‘p mahsulot bor.'),400
    parsed = []
    seen = set()
    for it in items:
        if not isinstance(it, dict): return jsonify(error='Mahsulot formati xato.'),400
        try:
            pid, qty = int(it.get('id')), int(it.get('quantity'))
        except (ValueError, TypeError): return jsonify(error='Mahsulot yoki soni noto‘g‘ri.'),400
        if pid <= 0 or pid in seen or qty < 1 or qty > 100:
            return jsonify(error='Mahsulot ID yoki miqdori noto‘g‘ri.'),400
        seen.add(pid)
        parsed.append((pid,qty))
    # Narx va valyuta faqat mahsulot bazasidan olinadi; mijoz yuborgan summaga ishonilmaydi.
    currency = None
    with connect() as db:
        try:
            db.execute('BEGIN IMMEDIATE')
            orders_items = []
            total = 0
            for pid,qty in parsed:
                product = db.execute('SELECT id,name,price,currency,unit FROM products WHERE id=? AND active=1', (pid,)).fetchone()
                if not product: db.rollback(); return jsonify(error='Savatdagi mahsulotlardan biri mavjud emas.'),409
                if currency is None: currency = product['currency']
                if product['currency'] != currency:
                    db.rollback()
                    return jsonify(error='So‘m va tenge mahsulotlarini alohida buyurtma qiling.'),409
                unit_price = int(product['price'])
                total += unit_price * qty
                orders_items.append((product,qty,int(unit_price)))
            if total > 10_000_000_000: db.rollback(); return jsonify(error='Buyurtma summasi haddan tashqari katta.'),400
            u = request.tg_user
            full_name = u['first_name'] + ' ' + u['last_name']
            username = (request.tg_identity.get('username') or u['username'] or '')[:40]
            cur = db.execute('''INSERT INTO orders(user_id,full_name,phone,username,region,city,address,
                              latitude,longitude,notes,total,currency,status,created_at)
                              VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)''',
                (u['tg_id'],full_name,u['phone'],username,region,city,address,lat,lon,notes,total,currency,'Yangi',now()))
            oid = cur.lastrowid
            db.executemany('''INSERT INTO order_items(order_id,product_id,product_name,unit,quantity,unit_price)
                              VALUES(?,?,?,?,?,?)''',
                [(oid,p['id'],p['name'],p['unit'],qty,unit_price) for p,qty,unit_price in orders_items])
            db.commit()
        except sqlite3.Error as ex:
            db.rollback()
            print('ORDER DB ERROR:', ex)
            return jsonify(error='Buyurtmani saqlashda xatolik yuz berdi.'),500
    order = db_one('SELECT * FROM orders WHERE id=?', (oid,))
    for admin_id in ADMIN_IDS:
        try:
            bot.send_message(admin_id, format_order(order), disable_web_page_preview=True)
            if lat is not None and lon is not None:
                bot.send_location(admin_id, lat, lon)
        except Exception as ex:
            print(f'Admin notify {admin_id}:', ex)
    try:
        bot.send_message(u['tg_id'], t_user(u['tg_id'],
            f'✅ Buyurtmangiz <b>#{oid}</b> qabul qilindi!\nJami: <b>{money(total, currency)}</b>\nHolatini /orders orqali tekshiring.',
            f'✅ Заказ <b>#{oid}</b> принят!\nИтого: <b>{money(total, currency)}</b>\nПроверяйте статус через /orders.'))
    except Exception as ex: print('user notification:', ex)
    return jsonify(ok=True, id=oid, total=total, currency=currency), 201


@app.post(WEBHOOK_PATH)
def telegram_webhook():
    if not hmac.compare_digest(request.headers.get('X-Telegram-Bot-Api-Secret-Token', ''), WEBHOOK_SECRET):
        return jsonify(error='Unauthorized'),403
    try:
        update = types.Update.de_json(request.get_data(as_text=True))
        bot.process_new_updates([update])
        return 'OK',200
    except Exception as ex:
        print('Telegram webhook exception:',ex)
        return jsonify(error='Cannot process update'),500


